    filter::new(&mut m, 0x2a002b50, filter::WEIGHT_LINEAR, 0.3f32, 0, 0.0f32); filter::new(&mut m, 0x2a002b30, filter::WEIGHT_QUADRATIC, 0.5f32, 0, 0.0f32);
    let before0 = m.read(0x2a001000, 16384);
